// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Reentrance} from "../src/Reentrance.sol";

contract InvMutTest is Test {
    Reentrance c;
    function setUp() public { c = new Reentrance(); }
    function testFuzz_property(uint256 depositAmount, uint256 withdrawAmount, address user) public {
        vm.assume(user != address(0));
        vm.assume(depositAmount > 0);
        vm.assume(withdrawAmount <= depositAmount);

        vm.deal(user, depositAmount);
        vm.prank(user);
        c.addToBalance{value: depositAmount}();

        uint256 balanceBeforeWithdraw = c.getBalance(user);
        assertTrue(balanceBeforeWithdraw == depositAmount);
    }
}
